["do_custom"] = true,
["custom"] = "local e = aura_env\nif not _G[e.id..\"Button\"] then\n    local region = WeakAuras.GetRegion(e.id)\n    e.btn = CreateFrame(\"Button\", e.id..\"Button\", region, \"SecureActionButtonTemplate\")\n    e.btn:RegisterForClicks(\"LeftButtonUp\", \"RightButtonUp\", \"LeftButtonDown\", \"RightButtonDown\")\n    e.btn:SetAttribute(\"type1\",\"macro\")\n    e.btn:SetAttribute(\"type2\",\"macro\")\n    e.btn:SetAllPoints(region)\nend\n\nlocal btn = _G[e.id..\"Button\"]\nbtn:SetAttribute(\"macrotext1\",\"/cast 传送门：塞拉摩\")\nbtn:SetAttribute(\"macrotext2\",\"/cast 传送：塞拉摩\")\n\nbtn:SetScript(\"OnEnter\", function(self)\n        GameTooltip:SetOwner(self, \"ANCHOR_RIGHT\")\n        GameTooltip:SetText(\"|cffffffff左键：|r传送门：塞拉摩|cff04f192（\"..GetItemCount(17032)..\"）|r\\n|cffffffff右键：|r传送：塞拉摩|cff04f192（\"..GetItemCount(17031)..\"）|r\", 0, 1, 0, 1, 1)\n        WeakAuras.ScanEvents(\"DOOR_BTN_SHOW\")\nend)\nbtn:SetScript(\"OnLeave\", function(self) \n        GameTooltip:Hide()\n        WeakAuras.ScanEvents(\"DOOR_BTN_HIDE\")\nend)",
