["init"] = {
["do_custom"] = true,
["custom"] = "local e = aura_env \nif not _G[e.id..\"Button\"] then \n    local region = WeakAuras.GetRegion(e.id) \n    e.btn = CreateFrame(\"Button\", e.id..\"Button\", region, \"SecureActionButtonTemplate\") \n    e.btn:RegisterForClicks(\"LeftButtonUp\", \"RightButtonUp\", \"MiddleButtonUp\")\n    e.btn:SetAttribute(\"type1\",\"macro\")\n    e.btn:SetAttribute(\"type2\",\"macro\")\n    e.btn:SetAttribute(\"type3\",\"macro\")\n    e.btn:SetAllPoints(region) \nend \n\nlocal btn = _G[e.id..\"Button\"] \nbtn:SetAttribute(\"macrotext1\",\"/cast 熔岩护甲\")\nbtn:SetAttribute(\"macrotext2\",\"/cast 魔甲术\")\nbtn:SetAttribute(\"macrotext3\",\"/cast 冰甲术\\n/cast 霜甲术\")\nbtn:SetScript(\"OnEnter\", function(self)               \n        GameTooltip:SetOwner(self, \"ANCHOR_RIGHT\") \n        GameTooltip:SetText(\n            \"|cffffffff露露的快捷按钮\\n左键：|r|cffdd4237\"..\"熔岩护甲\"..\"|r\\n\"..\n            \"|cffffffff右键：|r|cff45d8ff\"..\"法师护甲\"..\"|r\\n\"..\n            \"|cffffffff中键：|r|cff387add\"..\"冰甲术/霜甲术\"..\"|r\\n\"\n        , 0, 1, 0, 1, 1)\nend)\n\nbtn:SetScript(\"OnLeave\", function(self) GameTooltip:Hide() end)\nbtn:Show()",
},
